(async()=>{const status=document.getElementById('certificate-message');try{const {member}=await WildRideMember.session();if(!member)throw Error('請先登入會員，再從會員中心開啟證書。');const id=new URLSearchParams(location.search).get('id');const all=await WildRideMember.request(member.role==='admin'?'admin/overview':'assessments');const c=all.certificates.find(c=>c.id===id);if(!c)throw Error('找不到此證書，或你沒有查看權限。');if(c.revoked_at)throw Error('此證書已撤銷，無法列印。');const names={L1:'基礎控車・基礎林道',L2:'技術林道・硬耐力入門',L3:'硬耐力進階',wheelie:'孤輪專項',sand:'砂地專項',slide:'滑胎專項',jump:'跳躍專項'};for(const [key,value]of Object.entries({name:c.student_name,target:c.target+' / '+names[c.target],instructor:c.instructor,date:c.test_date,hours:c.hours?c.hours+' 小時':'未填寫',serial:c.serial}))document.getElementById('cert-'+key).textContent=value;document.getElementById('certificate-paper').hidden=false;document.getElementById('print-certificate').hidden=false;status.textContent='已確認有效證書。可使用列印功能另存 PDF。';document.getElementById('print-certificate').onclick=()=>window.print()}catch(e){status.textContent=e.message}})();
